import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"Emuera 引擎的使用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/Emuera_Engine.md","filePath":"guide/Emuera_Engine.md"}`),a={name:`guide/Emuera_Engine.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="emuera-引擎的使用" tabindex="-1">Emuera 引擎的使用 <a class="header-anchor" href="#emuera-引擎的使用" aria-label="Permalink to “Emuera 引擎的使用”">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to “前言”">​</a></h2><p>在正式写游戏之前，我们先把“舞台”认识清楚：Emuera 是什么？它有几种启动方式？一个游戏文件夹里都有些什么？这一节不写代码，但会让你后面的每一步都更踏实。</p><div class="warning custom-block"><p class="custom-block-title">教程依赖</p><p>本教程假设您已学习过<a href="./Quick_Start.html">快速开始</a>。若您尚未学习过，我们强烈推荐您首先学习相应教程。</p></div><h2 id="emuera-是什么" tabindex="-1">Emuera 是什么 <a class="header-anchor" href="#emuera-是什么" aria-label="Permalink to “Emuera 是什么”">​</a></h2><p><strong>Emuera</strong> 是一个用于运行 Era 系列游戏的引擎。它兼容更早期的 <strong>Eramaker</strong> 脚本，同时扩展了大量新语法。我们写的 <code>ERB</code> 脚本，最终就是交给它来执行的。</p><ul><li>引擎本体：一个 <code>EmueraXXXX.exe</code> 文件；</li><li>游戏内容：<code>CSV/</code> 里的数据文件，加上 <code>ERB/</code> 里的脚本；</li><li>配置：根目录下自动生成的 <code>emuera.config</code>。</li></ul><h2 id="三种启动模式" tabindex="-1">三种启动模式 <a class="header-anchor" href="#三种启动模式" aria-label="Permalink to “三种启动模式”">​</a></h2><p>Emuera 有两种常用的启动方式，区别在于“怎么启动它”。</p><h3 id="普通模式" tabindex="-1">普通模式 <a class="header-anchor" href="#普通模式" aria-label="Permalink to “普通模式”">​</a></h3><p>直接双击 <code>EmueraXXXX.exe</code>，就是普通模式。这是我们玩游戏、也是测试游戏时的默认模式。</p><h3 id="解析模式" tabindex="-1">解析模式 <a class="header-anchor" href="#解析模式" aria-label="Permalink to “解析模式”">​</a></h3><p>把 <code>ERB</code> 文件或文件夹<strong>拖到</strong> <code>EmueraXXXX.exe</code> 上，就会进入解析模式。它会检查被拖入文件有没有语法错误，非常适合在写代码时快速自检——不用真的把游戏跑起来，就能发现拼写、配对之类的低级错误。</p><h3 id="调试模式" tabindex="-1">调试模式 <a class="header-anchor" href="#调试模式" aria-label="Permalink to “调试模式”">​</a></h3><p>以命令行参数 <code>-debug</code> 启动 Emuera，就进入调试模式。调试模式能查看变量、逐行执行，是排错时的利器。详情可以参考<a href="./../translation/Debug_Mode.html">调试模式</a>。</p><h2 id="一个游戏文件夹里有什么" tabindex="-1">一个游戏文件夹里有什么 <a class="header-anchor" href="#一个游戏文件夹里有什么" aria-label="Permalink to “一个游戏文件夹里有什么”">​</a></h2><p>一个最精简的游戏文件夹（我们用 <code>root</code> 来代表）结构如下：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>root/</span></span>
<span class="line"><span> ├─ emuera.config      ← 引擎配置（首次运行时自动生成）</span></span>
<span class="line"><span> ├─ Emuera1824.exe     ← 引擎本体</span></span>
<span class="line"><span> ├─ CSV/               ← 数据文件</span></span>
<span class="line"><span> └─ ERB/               ← 脚本文件</span></span>
<span class="line"><span>     └─ System.erb     ← 我们写的脚本</span></span></code></pre></div><p>随着游戏变复杂，还会多出这些：</p><table tabindex="0"><thead><tr><th>文件夹/文件</th><th>用途</th></tr></thead><tbody><tr><td><code>resources/</code></td><td>图片等资源</td></tr><tr><td><code>sav/</code></td><td>存档、全局数据等</td></tr><tr><td><code>emuera.log</code></td><td>运行日志，报错时来这里找线索</td></tr></tbody></table><h2 id="配置对话框" tabindex="-1">配置对话框 <a class="header-anchor" href="#配置对话框" aria-label="Permalink to “配置对话框”">​</a></h2><p>在游戏窗口的菜单里可以打开<strong>设置对话框</strong>，里面能调整字体、颜色、是否显示存档列表等选项。大部分选项保持默认就好，等真正需要时再来调整。</p><p>想了解每一项的含义，可以查阅<a href="./../translation/Config.html">参考-配置文件</a>以及<a href="./../translation/Glossary.html">术语表</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><ul><li>Emuera 是运行 Era 系列游戏的引擎；</li><li>双击是普通模式，拖入文件是解析模式，加 <code>-debug</code> 是调试模式；</li><li>一个游戏 = <code>CSV/</code> + <code>ERB/</code> + <code>emuera.config</code>；</li><li>报错时，记得去根目录看 <code>emuera.log</code>。</li></ul><p>准备好了吗？让我们正式从第一个概念开始：<a href="./tutorials/Variable.html">常量与变量</a>。</p>`,26)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};